diff --git a/repro/check.js b/repro/check.js
new file mode 100644
index 000000000..17b5763ba
--- /dev/null
+++ b/repro/check.js
@@ -0,0 +1,54 @@
+// Usage (from the repo root):
+//   node repro/check.js [fixture.ts] [path/to/typescript.js]
+// Defaults: repro/report.ts and built/local/typescript.js.
+//
+// Asks the language service for the type of `Test` the way the Playground's `^?`
+// does (quick info), and also asks the checker to print it. The report expects
+// `{ prop1: "hello"; }`. Exits 1 if either printout differs, 0 if both match.
+"use strict";
+const fs = require("fs");
+const path = require("path");
+
+const fixture = path.resolve(process.argv[2] || path.join(__dirname, "report.ts"));
+const tsPath = path.resolve(process.argv[3] || path.join(__dirname, "..", "built", "local", "typescript.js"));
+const ts = require(tsPath);
+const expected = `{ prop1: "hello"; }`;
+const squash = s => s.replace(/\s+/g, " ").trim();
+
+const text = fs.readFileSync(fixture, "utf8");
+const options = { strict: true, target: ts.ScriptTarget.ESNext, types: [], noEmit: true };
+const host = {
+    getCompilationSettings: () => options,
+    getScriptFileNames: () => [fixture],
+    getScriptVersion: () => "1",
+    getScriptSnapshot: f => f === fixture
+        ? ts.ScriptSnapshot.fromString(text)
+        : ts.sys.fileExists(f) ? ts.ScriptSnapshot.fromString(ts.sys.readFile(f)) : undefined,
+    getCurrentDirectory: () => path.dirname(fixture),
+    getDefaultLibFileName: o => ts.getDefaultLibFilePath(o),
+    fileExists: ts.sys.fileExists,
+    readFile: ts.sys.readFile,
+    readDirectory: ts.sys.readDirectory,
+    directoryExists: ts.sys.directoryExists,
+    getDirectories: ts.sys.getDirectories,
+};
+const service = ts.createLanguageService(host, ts.createDocumentRegistry());
+
+const pos = text.indexOf("type Test =") + "type ".length;
+const quickInfo = ts.displayPartsToString(service.getQuickInfoAtPosition(fixture, pos).displayParts);
+
+const program = service.getProgram();
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(fixture);
+const alias = sf.statements.find(s => ts.isTypeAliasDeclaration(s) && s.name.text === "Test");
+const printed = checker.typeToString(checker.getTypeAtLocation(alias.name), undefined, ts.TypeFormatFlags.NoTruncation);
+
+console.log(`typescript ${ts.version} (${path.relative(process.cwd(), tsPath)})`);
+console.log(`fixture    ${path.relative(process.cwd(), fixture)}`);
+console.log(`expected   type Test = ${expected}`);
+console.log(`quick info ${squash(quickInfo)}`);
+console.log(`typeToString(Test) = ${squash(printed)}`);
+
+const ok = squash(quickInfo) === `type Test = ${expected}` && squash(printed) === expected;
+console.log(ok ? "PASS: Test is { prop1: \"hello\"; }" : "FAIL: Test is not { prop1: \"hello\"; }");
+process.exit(ok ? 0 : 1);
diff --git a/repro/report.ts b/repro/report.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/repro/report.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
